#!/usr/bin/env node
/**
 * Writes `site/out/_redirects` — the redirects that keep every story URL that has ever
 * been published working after ADR-0001 moved a story under its tier and genre.
 *
 *   pnpm build        # runs this as the last step of the site build
 *
 * Cloudflare Pages reads `_redirects` from the upload root, which is why this is generated
 * into `site/out` at build time rather than committed into `site/public`: a redirect list
 * that has to be regenerated by hand is a redirect list that goes stale the first time the
 * pipeline publishes a story, and a stale one 404s instead of failing.
 *
 * The destinations come from `site/lib/content.ts`, so they are the same `entry.url` the
 * canonical, the breadcrumb, the sitemap and the RSS feed use. Nothing here decides where
 * a story lives; it only records where one used to.
 *
 * A 301 rather than a rewrite: these addresses are gone for good, and a search engine that
 * is told so transfers what it knew to the new one.
 */
import fs from "node:fs";
import path from "node:path";
import process from "node:process";
import { getEntries } from "../site/lib/content.ts";

const ROOT = path.resolve(import.meta.dirname, "..");
const OUT = path.join(ROOT, "site", "out");

/** Where an entry of this kind used to live, before the tier segment existed. */
function legacyPath(kind, slug) {
  return kind === "story" ? `/stories/${slug}/` : `/classics/${slug}/`;
}

/*
 * Search-engine verification files have to answer at their exact `.html` address, and
 * Cloudflare Pages canonicalises a `.html` asset with a 308 to the extensionless path. A
 * 200 rewrite serves the same bytes at the address the crawler asked for, so a
 * verification file dropped into `site/public/` needs nothing else.
 */
const PUBLIC = path.join(ROOT, "site", "public");
const verificationFiles = fs.existsSync(PUBLIC)
  ? fs.readdirSync(PUBLIC).filter((name) => /^google[0-9a-f]+\.html$/.test(name)).sort()
  : [];
const rewrites = verificationFiles.map((name) => `/${name} /${name.replace(/\.html$/, "")} 200`);

const entries = getEntries();
const lines = [
  ...rewrites,
  // The static export writes the homepage as index.html, and Cloudflare Pages serves
  // /index.html as its own 200 with no canonical — a duplicate of / to a crawler.
  "/index.html / 301",
  ...entries.map((entry) => `${legacyPath(entry.kind, entry.slug)} ${entry.url} 301`),
];

/*
 * A redirect whose destination is also its source is a loop, and one that is written twice
 * is a rule nobody can predict. Neither can happen from the code above today; both are one
 * copy-paste away, and both are silent in a browser until a reader hits them.
 */
const sources = new Set();
for (const line of lines) {
  const [from, to] = line.split(" ");
  if (from === to) throw new Error(`_redirects: ${from} redirects to itself`);
  if (sources.has(from)) throw new Error(`_redirects: ${from} is listed twice`);
  sources.add(from);
}

if (!fs.existsSync(OUT)) {
  console.error("site/out does not exist — run `next build` first.");
  process.exit(1);
}

const header = [
  "# Generated by scripts/write-redirects.mjs — do not edit.",
  "# Every story URL from before the tier and genre segments (ADR-0001) is still here.",
  "# The 200 lines serve search-engine verification files at their exact .html address.",
  "",
];

fs.writeFileSync(path.join(OUT, "_redirects"), header.concat(lines, [""]).join("\n"));
console.log(
  `wrote site/out/_redirects — ${entries.length} redirect(s) from the pre-tier URLs, ` +
    `${rewrites.length} verification rewrite(s), 1 /index.html redirect`,
);
